def factorial(n):
    """
    Calculates the factorial of a non-negative integer n.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")
    elif n == 0:
        return 1
    else:
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

def factorial(n):
    """Calculates the factorial of a non-negative integer n."""
    if not isinstance(n, int): raise TypeError("Input must be an integer.")
    if n < 0: raise ValueError("Factorial is not defined for negative numbers.")
    if n == 0: return 1
    result = 1
    for i in range(1, n + 1): result *= i
    return result

def fibonacci(n):
    """Calculates the nth Fibonacci number (0-indexed)."""
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def fibonacci(n):
    """Calculates the nth Fibonacci number (0-indexed)."""
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

def fibonacci(n):
    """Returns the nth Fibonacci number (0-indexed)."""
    if n < 0: raise ValueError("Input must be non-negative.")
    return n if n < 2 else fibonacci(n - 1) + fibonacci(n - 2)

