def sum_digits(n):
    """
    Calculates the sum of all digits in a non-negative integer n using recursion.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")
    return n if n < 10 else n % 10 + sum_digits(n // 10)

def sum_digits(n):
    """Calculates the sum of all digits in a non-negative integer n."""
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    total_sum = 0
    while n > 0:
        total_sum += n % 10
        n //= 10
    return total_sum if total_sum > 0 or n == 0 else 0

def sum_digits(n):
    """
    Calculates the sum of all digits in a non-negative integer n using recursion.
    Assumes n is a non-negative integer.
    """
    if n < 10:
        return n
    return (n % 10) + sum_digits(n // 10)

