def fibonacci(n):
    # Base cases
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Dynamic programming approach
    # Initialize array to store Fibonacci numbers
    fib = [0] * (n + 1)
    fib[1] = 1

    # Compute Fibonacci numbers iteratively
    for i in range(2, n + 1):
        fib[i] = fib[i-1] + fib[i-2]

    return fib[n]

