def is_palindrome(s):
    """
    Returns True if string s is a palindrome (ignoring case), False otherwise.

    Args:
        s (str): The input string to check.
    """
    s = s.lower()
    def helper(s, i, j):
        if i >= j:
            return True
        return s[i] == s[j] and helper(s, i + 1, j - 1)
    return helper(s, 0, len(s) - 1)

