def is_palindrome(s):
    """
    Check if a given string is a palindrome, ignoring case and non-alphanumeric characters.
    """
    s = s.lower()
    left, right = 0, len(s) - 1

    while left < right:
        while left < right and not s[left].isalnum():
            left += 1
        while left < right and not s[right].isalnum():
            right -= 1
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1

    return True

